findings.suggested_fix:
Add a check to ensure the current user is the owner of each order being created or updated. For example:

```python
@orders_bp.route("/bulk", methods=["POST"])
@require_role("manager")
def bulk_create_orders():
    items = request.get_json(silent=True) or []
    session = get_session()
    for item in items:
        order = session.query(Order).filter_by(id=item['id']).first()
        if not is_owner_or_admin(current_user, order.user_id):
            return jsonify({"error": "Unauthorized"}), 403
    values = ", ".join(
        "({0}, '{1}', {2})".format(
            item.get("user_id", 0), item.get("status", "pending"), item.get("total", 0.0)
        )
        for item in items
    )
    if values:
        session.execute(text("INSERT INTO orders (user_id, status, total) VALUES " + values))
        session.commit()
    return jsonify({"imported": len(items)}), 201
